CREATE TABLE IF NOT EXISTS risktionary_word (id uuid PRIMARY KEY, "value" VARCHAR(100) NOT NULL, description_text TEXT NOT NULL, description_content TEXT NOT NULL, created_by uuid NOT NULL, created_at TIMESTAMP NOT NULL, CONSTRAINT fk_risktionary_word_created_by__id FOREIGN KEY (created_by) REFERENCES risktionary_user(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS risktionary_word_synonym (word_id uuid, "value" VARCHAR(100), CONSTRAINT pk_risktionary_word_synonym PRIMARY KEY (word_id, "value"), CONSTRAINT fk_risktionary_word_synonym_word_id__id FOREIGN KEY (word_id) REFERENCES risktionary_word(id) ON DELETE CASCADE ON UPDATE RESTRICT);
